The Lurking Storm.command:
const DamageRollClass = CONFIG.Dice.rolls.find(((R) => R.name === "DamageRoll"));
const damageRolls = game.messages
    .filter(it => it.rolls && it.rolls.length > 0)
    .slice(-1);

if(damageRolls.length < 1) {
   return ui.notifications.error("There has not been any damage rolled yet!") ;
}

const damageRoll = damageRolls[0];
const total = damageRoll.rolls[0]._total;


const splitDamage = new DamageRollClass(`(${Math.ceil(total/2)})[bludgeoning],(${Math.floor(total/2)})[electricity]`);
splitDamage.toMessage({
    flavor: `The Lurking Storm`,
    speaker: ChatMessage.getSpeaker()
});
